/**
 * @file Astro integration for Splendid Svelte.
 */

import { fileURLToPath } from 'node:url'
import { unbarrel } from './unbarrel.js'

/**
 * @import { AstroIntegration } from 'astro'
 */

/**
 * splendidSvelte
 * Loads each `@splendidlabz/svelte` component from its own file.
 *
 * @returns {AstroIntegration}
 */
export function splendidSvelte() {
  return {
    name: '@splendidlabz/svelte',
    hooks: {
      'astro:config:setup': ({ config, updateConfig }) => {
        updateConfig({
          vite: {
            plugins: [
              unbarrel({
                root: fileURLToPath(config.root),
                pkg: '@splendidlabz/svelte',
              }),
            ],
          },
        })
      },
    },
  }
}
